from collections import deque
# Use previously constructed G; binary occupancy
occ=(G!=0)
seen=np.zeros_like(occ,bool); comps=[]
for r in range(30):
 for c in range(30):
  if occ[r,c] and not seen[r,c]:
   q=deque([(r,c)]);seen[r,c]=1; cells=[]
   while q:
    x,y=q.popleft();cells.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<30 and 0<=b<30 and occ[a,b] and not seen[a,b]:seen[a,b]=1;q.append((a,b))
   marks={G[x,y] for x,y in cells if G[x,y]>1}
   comps.append((cells,marks))
[(len(c),m, (min(x for x,y in c),max(x for x,y in c),min(y for x,y in c),max(y for x,y in c))) for c,m in comps]

out2=G.copy()
for cells,marks in comps:
 if marks:
  color=next(iter(marks))
  for r,c in cells:
   if 0<r<29 and 0<c<29 and occ[r-1:r+2,c-1:c+2].all():out2[r,c]=int(color)
print('\n'.join(' '.join(map(str,row)) for row in out2))
